// Soft-fail handling for the organisation lookup, matching the PS script's
// try { Get-MgOrganization } catch { } - a failure here must NOT abort the run,
// and must NOT be hidden: we surface organisationLookupFailed downstream instead.

const cfg = $('Config').first().json;
const input = $input.first().json;

let displayName = null;
let verifiedDomains = [];
let orgLookupFailed = false;

if (input && Array.isArray(input.value) && input.value.length > 0) {
  const o = input.value[0];
  displayName = o.displayName || null;
  verifiedDomains = Array.isArray(o.verifiedDomains) ? o.verifiedDomains.map(d => d.name) : [];
} else {
  orgLookupFailed = true;
}

return [{
  json: {
    tenantDisplayName: displayName || cfg.organisationName,
    verifiedDomains,
    orgLookupFailed
  }
}];

// Licence/SKU exclusion + friendly-name mapping + utilisation calculation.
// Mirrors the DATA COLLECTION block of M365-WeeklyReport.ps1 that builds $licenceRows.

const cfg = $('Config').first().json;
const raw = $input.first().json.value || [];

const excludedSet = new Set(cfg.excludedSkus);
const filtered = raw.filter(s => !excludedSet.has(s.skuPartNumber));

const skuLookup = {};

const licenceRows = filtered.map(s => {
  const friendly = cfg.skuFriendlyNames[s.skuPartNumber] || s.skuPartNumber;
  skuLookup[s.skuId] = friendly;

  const total = Number((s.prepaidUnits && s.prepaidUnits.enabled) || 0);
  const warning = Number((s.prepaidUnits && s.prepaidUnits.warning) || 0);
  const assigned = Number(s.consumedUnits || 0);
  const available = total - assigned;
  const pctUsed = total > 0 ? Math.round((assigned / total) * 10000) / 10000 : 0;
  const pctWhole = Math.round(pctUsed * 100);

  let status = 'Healthy';
  if (pctWhole >= cfg.highUsagePct) status = 'Critical';
  else if (pctWhole >= cfg.mediumUsagePct) status = 'Watch';

  const action = status === 'Critical'
    ? 'Procure additional seats or reclaim unused licences'
    : status === 'Watch'
      ? 'Monitor consumption; plan procurement'
      : 'No action required';

  return {
    licenceSku: friendly,
    skuPartNumber: s.skuPartNumber,
    totalSeats: total,
    assigned,
    available,
    expiringSoon: warning,
    utilisation: pctUsed,
    status,
    recommendedAction: action
  };
});

licenceRows.sort((a, b) => b.totalSeats - a.totalSeats);

return [{ json: { licenceRows, skuLookup } }];

// Replaces the Graph SDK's -All pagination handling: each n8n pagination cycle
// produces one item per page fetched; concatenate every page's value[] array.

const pages = $input.all();
let users = [];

for (const page of pages) {
  const body = page.json;
  if (body && Array.isArray(body.value)) {
    users = users.concat(body.value);
  }
}

return [{ json: { users, totalFetched: users.length } }];

// Per-user normalisation - mirrors the foreach ($u in $users) block in the .ps1:
// domain extraction, licence-name resolution via skuLookup, status/type, account age.

const skuLookup = $('Filter and Map Licences').first().json.skuLookup;
const users = $input.first().json.users;
const now = Date.now();

const userReport = users.map(u => {
  const upn = u.userPrincipalName || '';
  const domain = upn.includes('@') ? upn.split('@').pop().toLowerCase() : 'unknown';

  const licenceNames = [];
  if (Array.isArray(u.assignedLicenses)) {
    for (const al of u.assignedLicenses) {
      const key = al.skuId;
      if (key && skuLookup[key]) licenceNames.push(skuLookup[key]);
    }
  }
  const uniqueLicenceNames = Array.from(new Set(licenceNames)).sort();
  const licenceText = uniqueLicenceNames.length > 0 ? uniqueLicenceNames.join('; ') : 'Unlicensed';

  let dateCreated = null;
  let accountAgeDays = null;
  if (u.createdDateTime) {
    dateCreated = u.createdDateTime;
    accountAgeDays = Math.floor((now - new Date(u.createdDateTime).getTime()) / 86400000);
  }

  return {
    displayName: u.displayName || 'Unknown',
    emailAddress: upn,
    domain,
    department: u.department || 'Not specified',
    jobTitle: u.jobTitle || 'Not specified',
    office: u.officeLocation || 'Not specified',
    accountStatus: u.accountEnabled ? 'Active' : 'Blocked',
    accountType: u.userType || 'Member',
    licencesAssigned: licenceText,
    licenceCount: uniqueLicenceNames.length,
    dateCreated,
    accountAgeDays
  };
});

userReport.sort((a, b) =>
  a.domain.localeCompare(b.domain) ||
  a.department.localeCompare(b.department) ||
  a.displayName.localeCompare(b.displayName)
);

return [{ json: { userReport, totalUsers: userReport.length } }];

// Domain segmentation - mirrors the 'Segmenting accounts by e-mail domain' block:
// dedicated-worksheet eligibility rules (always-include, minimum count, .onmicrosoft.com exclusion)
// plus the per-domain summary used on the Executive Summary sheet.

const cfg = $('Config').first().json;
const { userReport, totalUsers } = $input.first().json;

const groups = {};
for (const u of userReport) {
  if (!groups[u.domain]) groups[u.domain] = [];
  groups[u.domain].push(u);
}

const domainGroupsArr = Object.entries(groups)
  .map(([domain, rows]) => ({ domain, rows }))
  .sort((a, b) => b.rows.length - a.rows.length);

const dedicatedDomains = [];
for (const g of domainGroupsArr) {
  const d = g.domain;
  if (cfg.excludeOnMicrosoftDomain && d.endsWith('.onmicrosoft.com')) continue;
  const isMapped = Object.prototype.hasOwnProperty.call(cfg.domainDisplayNames, d);
  if (isMapped || g.rows.length >= cfg.minUsersForOwnTab) {
    if (!dedicatedDomains.includes(d)) dedicatedDomains.push(d);
  }
}
for (const d of cfg.alwaysIncludeDomains) {
  const dl = d.toLowerCase();
  if (!dedicatedDomains.includes(dl)) dedicatedDomains.push(dl);
}

const domainSummary = domainGroupsArr.map(g => {
  const rows = g.rows;
  const active = rows.filter(r => r.accountStatus === 'Active').length;
  const blocked = rows.filter(r => r.accountStatus === 'Blocked').length;
  const licensed = rows.filter(r => r.licenceCount > 0).length;
  const unlicensed = rows.filter(r => r.licenceCount === 0).length;
  return {
    domain: g.domain,
    totalAccounts: rows.length,
    active,
    blocked,
    licensed,
    unlicensed,
    shareOfTenant: totalUsers > 0 ? Math.round((rows.length / totalUsers) * 10000) / 10000 : 0,
    dedicatedWorksheet: dedicatedDomains.includes(g.domain) ? 'Yes' : 'No'
  };
});

return [{ json: { dedicatedDomains, domainSummary } }];

// Headline figures - mirrors the 'Headline figures' block of the .ps1.

const { userReport, totalUsers } = $('Normalise Users').first().json;
const { licenceRows } = $('Filter and Map Licences').first().json;
const { domainSummary } = $input.first().json;

const activeUsers = userReport.filter(u => u.accountStatus === 'Active').length;
const blockedUsers = userReport.filter(u => u.accountStatus === 'Blocked').length;
const unlicensed = userReport.filter(u => u.licenceCount === 0).length;
const guestUsers = userReport.filter(u => u.accountType === 'Guest').length;

const totalSeats = licenceRows.reduce((s, l) => s + l.totalSeats, 0);
const totalAssigned = licenceRows.reduce((s, l) => s + l.assigned, 0);
const totalAvailable = totalSeats - totalAssigned;
const totalPct = totalSeats > 0 ? Math.round((totalAssigned / totalSeats) * 1000) / 10 : 0;

return [{
  json: {
    totalUsers,
    activeUsers,
    blockedUsers,
    unlicensed,
    guestUsers,
    totalSeats,
    totalAssigned,
    totalAvailable,
    totalPct,
    domainsInUse: domainSummary.length
  }
}];

// Blocked Accounts + unlicensed analysis - mirrors the Blocked Accounts worksheet logic,
// including the 'still holding a licence' reclamation-candidate flag.

const { userReport } = $('Normalise Users').first().json;

const blockedRows = userReport
  .filter(u => u.accountStatus === 'Blocked')
  .sort((a, b) => a.domain.localeCompare(b.domain) || a.displayName.localeCompare(b.displayName));

const unlicensedRows = userReport.filter(u => u.licenceCount === 0);
const reclamationCandidates = blockedRows.filter(u => u.licenceCount > 0).length;

return [{
  json: {
    blockedRows,
    blockedCount: blockedRows.length,
    unlicensedRows,
    unlicensedCount: unlicensedRows.length,
    reclamationCandidates
  }
}];

// Reporting-period logic - a genuine week-ending calculation, replacing the .ps1's
// 'just relabel today as week ending' behaviour. See the sticky note above this node.

const cfg = $('Config').first().json;
const now = new Date();

const targetDow = typeof cfg.weekEndingDayOfWeek === 'number' ? cfg.weekEndingDayOfWeek : 0;
const currentDow = now.getDay();
let diff = currentDow - targetDow;
if (diff < 0) diff += 7;

const weekEndingDate = new Date(now);
weekEndingDate.setDate(now.getDate() - diff);
weekEndingDate.setHours(0, 0, 0, 0);

const dateStamp = weekEndingDate.toISOString().slice(0, 10);
const reportDateLong = weekEndingDate.toLocaleDateString('en-GB', {
  weekday: 'long', day: '2-digit', month: 'long', year: 'numeric'
});

return [{
  json: {
    dateStamp,
    reportDateLong,
    generatedAt: now.toISOString(),
    weekEndingIso: weekEndingDate.toISOString()
  }
}];

// Previous-week comparison - see the sticky note above this node for what this can
// and cannot be relied on for. Uses n8n workflow static data; no external dependency,
// but only one prior snapshot is retained.

const staticData = $getWorkflowStaticData('global');
const kpis = $('Compute KPIs').first().json;
const { licenceRows } = $('Filter and Map Licences').first().json;
const period = $('Reporting Period Logic').first().json;

const currentSnapshot = {
  weekEndingIso: period.weekEndingIso,
  totalUsers: kpis.totalUsers,
  activeUsers: kpis.activeUsers,
  blockedUsers: kpis.blockedUsers,
  unlicensed: kpis.unlicensed,
  guestUsers: kpis.guestUsers,
  totalSeats: kpis.totalSeats,
  totalAssigned: kpis.totalAssigned,
  totalPct: kpis.totalPct,
  licenceUtilisationBySku: Object.fromEntries(licenceRows.map(l => [l.skuPartNumber, l.utilisation]))
};

const previousSnapshot = staticData.previousSnapshot || null;

let comparisonAvailable = false;
let comparison = null;

if (previousSnapshot && previousSnapshot.weekEndingIso !== currentSnapshot.weekEndingIso) {
  comparisonAvailable = true;
  comparison = {
    previousWeekEndingIso: previousSnapshot.weekEndingIso,
    totalUsersDelta: currentSnapshot.totalUsers - previousSnapshot.totalUsers,
    activeUsersDelta: currentSnapshot.activeUsers - previousSnapshot.activeUsers,
    blockedUsersDelta: currentSnapshot.blockedUsers - previousSnapshot.blockedUsers,
    unlicensedDelta: currentSnapshot.unlicensed - previousSnapshot.unlicensed,
    totalAssignedDelta: currentSnapshot.totalAssigned - previousSnapshot.totalAssigned,
    totalPctDelta: Math.round((currentSnapshot.totalPct - previousSnapshot.totalPct) * 10) / 10
  };
}

// Persist this run's snapshot so next week's run can compare against it.
staticData.previousSnapshot = currentSnapshot;

return [{
  json: {
    comparisonAvailable,
    comparison
  }
}];

// Final consolidation - the single output contract for the not-yet-built Excel/email
// workflow. Nothing here fabricates data: organisationLookupFailed is carried through
// as an explicit flag rather than masked.

const cfg = $('Config').first().json;
const org = $('Handle Organisation Result').first().json;
const { licenceRows } = $('Filter and Map Licences').first().json;
const { userReport } = $('Normalise Users').first().json;
const { dedicatedDomains, domainSummary } = $('Compute Domain Segmentation').first().json;
const kpis = $('Compute KPIs').first().json;
const blocked = $('Blocked and Unlicensed Accounts').first().json;
const period = $('Reporting Period Logic').first().json;
const comparison = $('Previous-Week Comparison').first().json;

return [{
  json: {
    meta: {
      tenantDisplayName: org.tenantDisplayName,
      verifiedDomains: org.verifiedDomains,
      organisationLookupFailed: org.orgLookupFailed,
      organisationName: cfg.organisationName,
      reportOwner: cfg.reportOwner,
      dateStamp: period.dateStamp,
      reportDateLong: period.reportDateLong,
      generatedAt: period.generatedAt
    },
    kpis,
    licenceRows,
    userReport,
    domainSummary,
    dedicatedDomains,
    blockedRows: blocked.blockedRows,
    blockedCount: blocked.blockedCount,
    unlicensedRows: blocked.unlicensedRows,
    unlicensedCount: blocked.unlicensedCount,
    reclamationCandidates: blocked.reclamationCandidates,
    weekOverWeek: {
      available: comparison.comparisonAvailable,
      deltas: comparison.comparison
    },
    distribution: {
      senderMailbox: cfg.senderMailbox,
      recipientEmails: cfg.recipientEmails,
      ccEmails: cfg.ccEmails
    }
  }
}];

// Builds the full multi-sheet workbook with exceljs, mirroring the EXCEL WORKBOOK
// region of M365-WeeklyReport.ps1. See the sticky notes above for the hard
// exceljs dependency and the known fidelity gaps vs. the original EPPlus output.

const ExcelJS = require('exceljs');

const data = $input.first().json;

const requiredFields = ['meta', 'kpis', 'licenceRows', 'userReport', 'domainSummary', 'dedicatedDomains', 'blockedRows'];
const missing = requiredFields.filter(function (k) { return !(k in data); });
if (missing.length > 0) {
  throw new Error('Consolidated dataset is missing required field(s): ' + missing.join(', ') + '. Refusing to build a workbook from incomplete data.');
}

const meta = data.meta;
const cfg = $('Config').first().json;
const domainDisplayNames = cfg.domainDisplayNames || {};
const highUsagePct = typeof cfg.highUsagePct === 'number' ? cfg.highUsagePct : 90;
const mediumUsagePct = typeof cfg.mediumUsagePct === 'number' ? cfg.mediumUsagePct : 70;
const kpis = data.kpis;
const licenceRows = data.licenceRows;
const userReport = data.userReport;
const domainSummary = data.domainSummary;
const dedicatedDomains = data.dedicatedDomains;
const blockedRows = data.blockedRows;

// ---- Corporate palette (presentation-only - not business logic, defined locally) ----
const PALETTE = {
  headerBg: 'FF1F3864', headerText: 'FFFFFFFF', title: 'FF1F3864', accent: 'FF2E5E9E',
  bandFill: 'FFF2F5FA',
  goodBg: 'FFE2EFDA', goodText: 'FF375623',
  watchBg: 'FFFFF2CC', watchText: 'FF7F6000',
  criticalBg: 'FFFBE5E5', criticalText: 'FF9C0006',
  borderGrey: 'FFC8CDD7'
};

function statusColours(status) {
  if (status === 'Blocked' || status === 'Critical') return { bg: PALETTE.criticalBg, fg: PALETTE.criticalText };
  if (status === 'Watch') return { bg: PALETTE.watchBg, fg: PALETTE.watchText };
  return { bg: PALETTE.goodBg, fg: PALETTE.goodText };
}

// ---- Worksheet name sanitising: Excel max 31 chars, no : \ / ? * [ ] ----
function safeSheetName(name) {
  let clean = String(name).replace(/[:\\\/\?\*\[\]]/g, '-').trim();
  if (clean.length > 31) clean = clean.substring(0, 31);
  if (!clean) clean = 'Sheet';
  return clean;
}
const usedNames = new Set();
function uniqueSheetName(name) {
  const base = safeSheetName(name);
  let candidate = base;
  let i = 2;
  while (usedNames.has(candidate.toLowerCase())) {
    const suffix = ' (' + i + ')';
    const trim = Math.min(base.length, 31 - suffix.length);
    candidate = base.substring(0, trim) + suffix;
    i++;
  }
  usedNames.add(candidate.toLowerCase());
  return candidate;
}

function escAmp(s) { return String(s == null ? '' : s).replace(/&/g, '&&'); }

// ---- Column width approximation - exceljs has no native AutoFitColumns ----
function autoFitColumn(ws, colIndex, values, opts) {
  const min = (opts && opts.min) || 9;
  const max = (opts && opts.max) || 55;
  let widest = 0;
  for (const v of values) {
    const len = v == null ? 0 : String(v).length;
    if (len > widest) widest = len;
  }
  ws.getColumn(colIndex).width = Math.max(min, Math.min(max, widest + 2));
}

const workbook = new ExcelJS.Workbook();
workbook.creator = meta.reportOwner;
workbook.lastModifiedBy = meta.reportOwner;
workbook.created = new Date();
workbook.modified = new Date();

// ============================================================================
// Shared sheet styling helper - equivalent of Format-ReportSheet in the .ps1
// ============================================================================
function formatReportSheet(ws, opts) {
  const title = opts.title;
  const subtitle = opts.subtitle;
  const headerRow = opts.headerRow || 4;
  const columnCount = opts.columnCount || 1;
  const lastDataRow = opts.lastDataRow || 4;
  const noFreeze = !!opts.noFreeze;
  const lastCol = Math.max(columnCount, 1);

  ws.mergeCells(1, 1, 1, lastCol);
  const titleCell = ws.getCell(1, 1);
  titleCell.value = title;
  titleCell.font = { size: 16, bold: true, color: { argb: PALETTE.title } };
  titleCell.alignment = { vertical: 'middle' };
  ws.getRow(1).height = 26;

  ws.mergeCells(2, 1, 2, lastCol);
  const subCell = ws.getCell(2, 1);
  subCell.value = subtitle || (meta.tenantDisplayName + '  |  ' + meta.reportDateLong);
  subCell.font = { size: 10, italic: true, color: { argb: 'FF5A5A5A' } };
  for (let c = 1; c <= lastCol; c++) {
    ws.getCell(2, c).border = { bottom: { style: 'medium', color: { argb: PALETTE.accent } } };
  }

  if (lastDataRow >= headerRow) {
    for (let c = 1; c <= lastCol; c++) {
      const hc = ws.getCell(headerRow, c);
      hc.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: PALETTE.headerBg } };
      hc.font = { bold: true, color: { argb: PALETTE.headerText } };
      hc.alignment = { horizontal: 'center', vertical: 'middle', wrapText: true };
    }
    ws.getRow(headerRow).height = 30;

    for (let r = headerRow + 1; r <= lastDataRow; r++) {
      for (let c = 1; c <= lastCol; c++) {
        const cell = ws.getCell(r, c);
        cell.alignment = Object.assign({ vertical: 'middle' }, cell.alignment);
        cell.border = {
          top: { style: 'thin', color: { argb: PALETTE.borderGrey } },
          bottom: { style: 'thin', color: { argb: PALETTE.borderGrey } },
          left: { style: 'thin', color: { argb: PALETTE.borderGrey } },
          right: { style: 'thin', color: { argb: PALETTE.borderGrey } }
        };
      }
    }

    ws.views = noFreeze
      ? [{ showGridLines: false }]
      : [{ state: 'frozen', ySplit: headerRow, showGridLines: false }];
  } else {
    ws.views = [{ showGridLines: false }];
  }

  ws.pageSetup = {
    orientation: 'landscape',
    fitToPage: true,
    fitToWidth: 1,
    fitToHeight: 0,
    margins: { top: 0.5, bottom: 0.5, left: 0.4, right: 0.4, header: 0.2, footer: 0.2 }
  };
  if (lastDataRow >= headerRow) {
    ws.pageSetup.printTitlesRow = headerRow + ':' + headerRow;
  }
  ws.headerFooter = {
    oddFooter: '&L' + escAmp(meta.tenantDisplayName) + ' - Microsoft 365 Weekly Report&CConfidential - Internal Use Only&RPage &P of &N'
  };
}

function addStatusFormatting(ws, colIndex, headerRow, lastRow) {
  for (let r = headerRow + 1; r <= lastRow; r++) {
    const raw = ws.getCell(r, colIndex).value;
    const c = statusColours(raw);
    const cell = ws.getCell(r, colIndex);
    cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: c.bg } };
    cell.font = Object.assign({ bold: true, color: { argb: c.fg } }, cell.font);
  }
}

// ============================================================================
// WORKSHEET 1 - COVER SHEET
// ============================================================================
const coverName = uniqueSheetName('Cover Sheet');
const wsCover = workbook.addWorksheet(coverName);
wsCover.getColumn(1).width = 34;
wsCover.getColumn(2).width = 70;
wsCover.views = [{ showGridLines: false }];
wsCover.pageSetup = { orientation: 'portrait' };

const coverLines = [
  { r: 2, text: meta.tenantDisplayName, size: 22, bold: true, colour: PALETTE.title },
  { r: 3, text: 'Microsoft 365 - Weekly Tenant Report', size: 16, bold: true, colour: PALETTE.accent },
  { r: 4, text: meta.reportDateLong, size: 11, bold: false, colour: 'FF5A5A5A' },
  { r: 7, text: 'REPORT DETAILS', size: 11, bold: true, colour: PALETTE.title }
];
for (const line of coverLines) {
  const cell = wsCover.getCell('A' + line.r);
  cell.value = line.text;
  cell.font = { size: line.size, bold: line.bold, color: { argb: line.colour } };
}
for (let c = 1; c <= 4; c++) {
  wsCover.getCell(3, c).border = { bottom: { style: 'medium', color: { argb: PALETTE.accent } } };
}

const metaRows = [
  ['Report title', 'Microsoft 365 Weekly Tenant Report'],
  ['Reporting period', 'Week ending ' + meta.reportDateLong],
  ['Prepared by', meta.reportOwner],
  ['Generated on', meta.generatedAt],
  ['Verified domains', (meta.verifiedDomains && meta.verifiedDomains.length) ? meta.verifiedDomains.join(', ') : 'Not available'],
  ['Total accounts', kpis.totalUsers],
  ['Classification', 'Confidential - Internal Use Only'],
  ['Distribution', (data.distribution.recipientEmails || []).join(', ')]
];
let row = 8;
for (const pair of metaRows) {
  wsCover.getCell('A' + row).value = pair[0];
  wsCover.getCell('A' + row).font = { bold: true };
  wsCover.getCell('B' + row).value = String(pair[1]);
  wsCover.getCell('A' + row).border = { bottom: { style: 'hair' } };
  wsCover.getCell('B' + row).border = { bottom: { style: 'hair' } };
  row++;
}

if (meta.organisationLookupFailed) {
  row++;
  const warnCell = wsCover.getCell('A' + row);
  warnCell.value = 'Note: the tenant organisation lookup failed for this run; the configured organisation name was used instead.';
  warnCell.font = { italic: true, color: { argb: PALETTE.criticalText } };
  row++;
}

row += 2;
wsCover.getCell('A' + row).value = 'CONTENTS';
wsCover.getCell('A' + row).font = { bold: true, size: 11, color: { argb: PALETTE.title } };
row++;
const contents = [
  'Executive Summary       - headline metrics and per-domain breakdown',
  'Licence Utilisation     - seats purchased, assigned, available and status',
  'Domain worksheets       - one worksheet per e-mail domain',
  'Blocked Accounts        - accounts with sign-in blocked',
  'Full User Directory     - complete tenant account listing'
];
for (const c of contents) {
  wsCover.getCell('A' + row).value = c;
  row++;
}

row += 2;
wsCover.getCell('A' + row).value = 'STATUS LEGEND';
wsCover.getCell('A' + row).font = { bold: true, color: { argb: PALETTE.title } };
row++;
const legend = [
  { label: 'Healthy / Active', desc: 'Licence utilisation below ' + mediumUsagePct + '% | account sign-in permitted', bg: PALETTE.goodBg, fg: PALETTE.goodText },
  { label: 'Watch', desc: 'Licence utilisation between ' + mediumUsagePct + '% and ' + highUsagePct + '%', bg: PALETTE.watchBg, fg: PALETTE.watchText },
  { label: 'Critical / Blocked', desc: 'Licence utilisation at or above ' + highUsagePct + '% | sign-in blocked', bg: PALETTE.criticalBg, fg: PALETTE.criticalText }
];
for (const l of legend) {
  const lc = wsCover.getCell('A' + row);
  lc.value = l.label;
  lc.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: l.bg } };
  lc.font = { bold: true, color: { argb: l.fg } };
  lc.alignment = { horizontal: 'center' };
  wsCover.getCell('B' + row).value = l.desc;
  row++;
}

row += 2;
const noticeCell = wsCover.getCell('A' + row);
noticeCell.value = "This document contains personal and licensing data. Handle in accordance with the organisation's information security policy.";
noticeCell.font = { italic: true, size: 9, color: { argb: 'FF787878' } };

// ============================================================================
// WORKSHEET 2 - EXECUTIVE SUMMARY
// ============================================================================
const summaryName = uniqueSheetName('Executive Summary');
const wsSum = workbook.addWorksheet(summaryName);

const kpiRows = [
  ['Total accounts', kpis.totalUsers, 'All member and guest accounts in the tenant'],
  ['Active accounts', kpis.activeUsers, 'Sign-in permitted'],
  ['Blocked accounts', kpis.blockedUsers, 'Sign-in blocked - review for licence reclamation'],
  ['Guest accounts', kpis.guestUsers, 'External collaborators'],
  ['Unlicensed accounts', kpis.unlicensed, 'No subscription assigned'],
  ['Total licence seats', kpis.totalSeats, 'Purchased across all reported SKUs'],
  ['Seats assigned', kpis.totalAssigned, 'Currently consumed'],
  ['Seats available', kpis.totalAvailable, 'Free capacity for new starters'],
